data.variablesTransform:
(
  /* Grab Information about the Request */
  $quantityToMove := ($state.context.REQUEST.mergeAll=true) ? $state.context.QUERY.fromInventory.edges.node.quantity.value : $state.context.REQUEST.mergeQuantity;

  /* Grab information about the inventory currently in the system */
  $quantityUnitId := $state.context.QUERY.fromInventory.edges.node.quantity.unitId;
  $fromWeightPerUnit := $coalesce([$state.context.QUERY.fromInventory.edges.node.netWeight,0])/$state.context.QUERY.fromInventory.edges.node.quantity.value;

  $fromInventory := $state.context.QUERY.fromInventory.edges.node.id;
  $fromQuantity := $state.context.QUERY.fromInventory.edges.node.quantity.value - $quantityToMove;
  $fromTareWeight := $coalesce([$state.context.QUERY.fromInventory.edges.node.tareWeight,0]); 
  $fromNetWeight := $fromWeightPerUnit * $fromQuantity;
  $fromGrossWeight := $fromTareWeight + $fromNetWeight;

  $toInventory := $state.context.QUERY.toInventory.edges.node.id;
  $toQuantity := $state.context.QUERY.toInventory.edges.node.quantity.value + $quantityToMove;
  $toTareWeight := $coalesce([$state.context.QUERY.toInventory.edges.node.tareWeight,0]); 
  $toNetWeight := $coalesce([$state.context.QUERY.toInventory.edges.node.netWeight,0]) + ($fromWeightPerUnit * $quantityToMove);
  $toGrossWeight := $toTareWeight + $toNetWeight;

  /* Grab information about the transaction type to use for new containers */
  $newTransactionTypeId := $state.context.QUERY.transactionType.edges.node.id;

  {
    "fromPayload": [
      {
        "update": {
          "active": ($fromQuantity>0),
          "netWeight": $fromNetWeight,
          "grossWeight": $fromGrossWeight,
          "quantity": {
            "value": $fromQuantity,
            "unitId": $quantityUnitId
          }
        },
        "where": {
          "id": $fromInventory
        }
      }
    ],
    "toPayload": [
      {
        "update": {
          "netWeight": $toNetWeight,
          "grossWeight": $toGrossWeight,
          "quantity": {
            "value": $toQuantity,
            "unitId": $quantityUnitId
          }
        },
        "where": {
          "id": $toInventory
        }
      }
    ]
  }
)

data.mutation:
mutation createUpdateInventory($fromPayload:[InventoryUpdatePayloadInput!]!, $toPayload:[InventoryUpdatePayloadInput!]!){
  updateFrom: updateInventory(payload:$fromPayload){
    id
    number
    productStrategyProcessId
  }
  updateTo: updateInventory(payload:$toPayload){
    id
    number
    productStrategyProcessId
  }
}

data.query:
query Query($whereIF: InventoryWhereInput, $whereIT: InventoryWhereInput,$wherePSM: ProductionSetupMaterialWhereInput) {
  fromInventory: inventory(where: $whereIF) {
    edges {
      node {
        id
        grossWeight

        netWeight
        tareWeight
        theoreticalWeight

        active
        barcode
        note
        trackingNumber
        customData
        quantity {
          value
          unitId
        }
        inventoryStatus {
          id
          name
          active
          containment
          defective
          loaded
          mergePrevent
          movePrevent
          picked
          productionLoaded
          productionPrevent
          received
          shipPrevent
          shipped
          splitPrevent
          staged
          suspect
          system
          usable
          color
          externalId
          message
        }
        locationId
        productStrategyProcessId
        lotId
        masterInventoryId
        packagingMaterialId
        supplierId
        weightUnitId
        workOrderId
        workOrderProcessId
      }
    }
  }
   toInventory: inventory(where: $whereIT) {
    edges {
      node {
        id
        grossWeight

        netWeight
        tareWeight
        theoreticalWeight

        active
        barcode
        note
        trackingNumber
        customData
        quantity {
          value
          unitId
        }
        inventoryStatus {
          id
          name
          active
          containment
          defective
          loaded
          mergePrevent
          movePrevent
          picked
          productionLoaded
          productionPrevent
          received
          shipPrevent
          shipped
          splitPrevent
          staged
          suspect
          system
          usable
          color
          externalId
          message
        }
        locationId
        productStrategyProcessId

        lotId
        masterInventoryId
        packagingMaterialId

        supplierId
        weightUnitId
        workOrderId
        workOrderProcessId
      }
    }
  }
    transactionType(where:{inventoryMerge:{_eq:true}} first:1) {
    edges {
      node {
        id
      }
    }
  }
  productionSetupMaterial(where:$wherePSM) {
    edges {
      node {
        id
        number
        inventory {
          id
          number
        }
        productionSetup {
          id
          workcenter {
            name
          }
        }
      }
    }
  } 
}

